    ["Nothing yet."] = "Поки порожньо.",
    ["Opening the editor in your browser. Switch to your browser if it does not come to the front."] = "Редактор відкривається у браузері. Якщо вікно не з’явилося, перейди до браузера.",
    ["Parts of the character"] = "Частини персонажа",
    ["Picked up in your talks"] = "Дізналися з твоїх розмов",
    ["Reset everything"] = "Скинути все",
    ["Reset to default"] = "Скинути до стандартного",
    ["Save"] = "Зберегти",
    ["Saved."] = "Збережено.",
    ["Search characters"] = "Пошук персонажів",
    ["Short facts you write yourself, such as a name or a promise. The character knows them in every talk."] = "Короткі факти, які ти пишеш сам, наприклад ім’я чи обіцянку. Персонаж знає їх у кожній розмові.",
    ["Short rules this character always follows when talking, for example: Never swear. Answer in one sentence."] = "Короткі правила, яких персонаж завжди дотримується в розмові, наприклад: Не лайся. Відповідай одним реченням.",
    ["Short summary of earlier talks"] = "Короткий підсумок попередніх розмов",
    ["Speaking rules"] = "Правила мовлення",
    ["Speaking style"] = "Манера мовлення",
    ["Story characters"] = "Персонажі сюжету",
    ["That character was not found."] = "Цього персонажа не знайдено.",
    ["The Local AI pack finds these. It is not installed or not ready, so none are collected now."] = "Пакет Local AI знаходить їх. Він не встановлений або не готовий, тому зараз нічого не збирається.",
    ["The bio is too long. Keep it under {max} characters."] = "Біографія занадто довга. Тримай її коротшою за {max} символів.",
    ["The bio is too short. Use at least {max} characters."] = "Біографія занадто коротка. Напиши щонайменше {max} символів.",
    ["The conversation service is not running, so the editor cannot open. Restart the game."] = "Служба розмов не запущена, тому редактор не може відкритися. Перезапусти гру.",
    ["The editor could not be opened. Try again."] = "Не вдалося відкрити редактор. Спробуй ще раз.",
    ["The editor is closed. You can close this tab."] = "Редактор закрито. Цю вкладку можна закрити.",
    ["The example lines are too long together. Keep them under {max} characters in all."] = "Приклади реплік разом занадто довгі. Тримай їх у сумі коротшими за {max} символів.",
    ["The speaking style is too long. Keep it under {max} characters."] = "Манера мовлення занадто довга. Тримай її коротшою за {max} символів.",
    ["Things they always know"] = "Що вони завжди знають",
    ["Too many example lines. Keep {max} or fewer."] = "Забагато прикладів реплік. Залиш не більше {max}.",
    ["Too many memories. Keep {max} or fewer."] = "Забагато спогадів. Залиш не більше {max}.",
    ["Too many rules. Keep {max} or fewer."] = "Забагато правил. Залиш не більше {max}.",
    ["Who this character is, what they know and how they look. A long bio makes replies slower, so keep it tight."] = "Хто цей персонаж, що він знає і як виглядає. Довга біографія уповільнює відповіді, тож пиши коротко.",
    ["You have changes that are not saved. Leave without saving?"] = "Є незбережені зміни. Вийти без збереження?",
    ["{count} of {max}"] = "{count} з {max}",
    ["Mature content"] = "Контент для дорослих",
    ["Companions can see"] = "Супутники бачать",
    ["With each line, the character also gets a recent picture of your surroundings, taken from the game window a few seconds before you started talking.\n\nOnly the game window is captured, only while someone you can talk to is near, and pictures are kept in memory for a short time, never saved. Works with Convai only."] = "З кожною реплікою персонаж отримує й свіжий знімок довкілля, зроблений з вікна гри за кілька секунд до початку розмови.\n\nЗнімається лише вікно гри, лише коли поруч є з ким поговорити; знімки недовго зберігаються в пам’яті й ніколи не записуються. Працює лише з Convai.",
    ["Local AI model"] = "Модель локального ШІ",
    ["Uncensored model"] = "Модель без цензури",
    ["No model installed"] = "Модель не встановлено",
    ["another model"] = "інша модель",
    ["The Local AI model you chose is missing, does not fit in the free graphics memory or did not start, so {model} was used instead."] = "Вибраної тобою моделі локального ШІ немає, вона не вміщується у вільну графічну пам'ять або не запустилася, тому натомість використано {model}.",
    ["Choose one of the listed Local AI models."] = "Вибери одну з переліку моделей локального ШІ.",
    ["Deletes the saved key. The Inworld cloud voice stops until you add a key again."] = "Видаляє збережений ключ. Хмарний голос Inworld не працюватиме, доки ти знову не додаси ключ.",
    ["Inworld cloud voice"] = "Хмарний голос Inworld",
    ["Inworld did not accept that key."] = "Inworld не прийняв цей ключ.",
    ["Inworld API key"] = "Ключ API Inworld",
    ["The Inworld cloud voice speaks only English here. Turn off Multilingual conversations to choose it."] = "Хмарний голос Inworld тут говорить лише англійською. Щоб вибрати його, вимкни «Багатомовні розмови».",
    ["{voice} · needs Inworld key"] = "{voice} · потрібен ключ Inworld",
    ["Characters to invite"] = "Персонажі для запрошення",
    ["Whose memories"] = "Чиї спогади",
    ["Invalid Mature content settings."] = "Недійсні налаштування контенту для дорослих.",
    ["Your message was not sent. Open the text box again and retype it."] = "Ваше повідомлення не надіслано. Відкрийте текстове поле знову й введіть його ще раз.",
    ["Not usable: {models}. See the Local AI notes, \"Add your own model\"."] = "Недоступні: {models}. Див. нотатки про локальний ШІ, розділ «Додавання власної моделі».",
    ["an embedding model, not a chat model"] = "модель ембедингів, а не чат-модель",
    ["could not be read"] = "не вдалося прочитати",
    ["file not found"] = "файл не знайдено",
    ["not a valid GGUF file"] = "не є дійсним файлом GGUF",
    ["{name} (custom)"] = "{name} (власна)",
    ["{name}: {reason}"] = "{name}: {reason}",
    ["Preparing {name}: waiting for the conversation service to connect…"] = "Підготовка {name}: очікування підключення служби розмов…",
    ["Preparing {name}: waiting for the voice model to load…"] = "Підготовка {name}: очікування завантаження голосової моделі…",
    ["Preparing {name}: waiting for the conversation connection to open…"] = "Підготовка {name}: очікування відкриття з'єднання для розмови…",
    ["Preparing {name}: waiting for the game to place the character…"] = "Підготовка {name}: очікування, поки гра розмістить персонажа…",
    ["Preparing {name}: waiting for the memory service…"] = "Підготовка {name}: очікування служби пам'яті…",
    ["Preparing {count} more companions…"] = "Підготовка інших супутників: {count}…",
    ["The conversation service did not answer. Wait a moment, then invite again."] = "Служба розмов не відповіла. Зачекай мить і запроси знову.",
    ["The voice model did not load. Check the voice in Settings or choose another one, then invite again."] = "Голосову модель не вдалося завантажити. Перевір голос у Налаштуваннях або вибери інший і запроси знову.",
    ["The memory service did not respond. Check your connection, then invite again."] = "Служба пам'яті не відповіла. Перевір з'єднання і запроси знову.",
    ["The conversation connection did not open. Check your connection, then invite again."] = "З'єднання для розмови не відкрилося. Перевір з'єднання і запроси знову.",
    ["Calls are not available during combat."] = "Дзвінки недоступні під час бою.",
    ["Calls are not available right now."] = "Дзвінки зараз недоступні.",
    ["Holocall ended: combat started."] = "Голодзвінок завершено: почався бій.",
    ["Holocall with {name} ended."] = "Голодзвінок з {name} завершено.",
    ["Holocall with {name}. Tap the phone button to hang up."] = "Голодзвінок з {name}. Натисніть кнопку телефона, щоб завершити.",
    ["Live holocall picture (experimental)"] = "Живе зображення в голодзвінку (експериментально)",
    ["YouTube on V’s TV"] = "YouTube на телевізорі V",
    ["Cyberpunk Convai: YouTube on the TV"] = "Cyberpunk Convai: YouTube на телевізорі",
    ["In V’s apartments the TV offers YouTube: pick a video and watch it with your companion, who can talk about it.\n\nThe video plays in a window over the game, so use Windowed Borderless or Windowed mode. On the couch, use the key binding YouTube on the TV (Cyberpunk Convai, in the CET bindings)."] = "У квартирах V телевізор пропонує YouTube: оберіть відео та дивіться його разом зі своїм компаньйоном, який може розповісти про нього.\n\nВідео відтворюється у вікні над грою, тож є два режими: Вікно без рамок або Вікно. На дивані використовуйте комбінацію клавіш YouTube на телевізорі (Cyberpunk Convai, у налаштуваннях клавіш CET).",
    ["YouTube"] = "YouTube",
    ["YouTube: pause or play"] = "YouTube: пауза або відтворення",
    ["YouTube: stop"] = "YouTube: зупинити",
    ["YouTube could not open on the TV. Try again."] = "Не вдалося відкрити YouTube на телевізорі. Спробуйте ще раз.",
    ["YouTube could not open on the TV. Use Windowed Borderless or Windowed mode and try again."] = "Не вдалося відкрити YouTube на телевізорі. Використайте режим Вікно без рамок або Вікно та спробуйте ще раз.",
    ["YouTube on the TV works in V's apartments."] = "YouTube на телевізорі працює в квартирах V.",
    ["YouTube on the TV is turned off in the settings."] = "YouTube на телевізорі вимкнено в налаштуваннях.",
    ["YouTube on the TV"] = "YouTube на телевізорі",
    ["Paste a YouTube link or video id"] = "Вставте посилання на YouTube або ID відео",
    ["Search YouTube"] = "Пошук на YouTube",
    ["Search"] = "Пошук",
    ["Recently watched"] = "Нещодавно переглянуті",
    ["Close"] = "Закрити",
    ["That is not a YouTube link or video id."] = "Це не посилання на YouTube і не ID відео.",
    ["This video cannot be played here. Choose another one."] = "Це відео тут не можна відтворити. Виберіть інше.",
    ["Loading…"] = "Завантаження…",
    ["Pick a video, then click back into the game. Use the TV to pause or stop it."] = "Виберіть відео, а потім поверніться до гри. Телевізором можна призупинити або зупинити відео.",
    ["Live picture unavailable. The call continues with the portrait."] = "Живе зображення недоступне. Дзвінок триває з портретом.",
    ["This contact cannot take a holocall."] = "Цей контакт не може прийняти голодзвінок.",
    ["You are already on a call."] = "Ви вже в розмові.",
    ["A nearby companion makes one short comment as combat starts and another afterward.\n\nTen-minute cooldown after a fight. Conversations and story scenes come first. Loading a save resets the cooldown."] = "Коли починається бій, найближчий компаньйон коротко коментує, а потім ще раз — після нього.\n\nПісля бою — десятихвилинна пауза. Розмови та сюжетні сцени важливіші. Завантаження збереження скидає паузу.",
    ["Ask a companion to drive to your selected map waypoint.\n\nGet into the passenger seat when they are ready."] = "Попроси компаньйона відвезти тебе до обраної на карті позначки.\n\nСідай на пасажирське місце, коли він буде готовий.",
    ["Auto: follows the completed encounter in this save.\n\nCasual: speaks with that familiarity.\n\nOrdinary: keeps her usual manner.\n\nIt does not imply an ongoing relationship."] = "Авто: орієнтується на завершену зустріч у цьому збереженні.\n\nНевимушений: говорить з такою самою невимушеністю.\n\nЗвичайний: зберігає її звичну манеру.\n\nЦе не означає тривалих стосунків.",
    ["Auto: follows the relationship in this save.\n\nRomantic: speaks to V as a partner.\n\nOrdinary: keeps their usual manner.\n\nOnly changes how they talk, never your game choices."] = "Авто: орієнтується на стосунки в цьому збереженні.\n\nРомантичний: звертається до V як до партнера.\n\nЗвичайний: зберігає свою звичну манеру.\n\nЗмінює лише манеру мовлення, але не ігрові вибори.",
    ["Bluetooth audio arrives a little late, so lips and subtitles can run ahead of the voice. This holds them back to match, for every voice.\n\nAuto: 150 ms while Windows plays through Bluetooth, none otherwise. Pick a value if your headset is faster or slower.\n\nThe game’s own dialogue has the same delay and does not correct it."] = "Звук через Bluetooth приходить трохи із запізненням, тож губи й субтитри можуть випереджати голос. Це налаштування притримує їх, щоб узгодити з голосом, для всіх голосів.\n\nАвто: 150 ms, поки Windows відтворює звук через Bluetooth, інакше нічого. Вибери значення, якщо твоя гарнітура швидша чи повільніша.\n\nВласні репліки гри мають таку саму затримку й не виправляються.",
    ["Changes this mod’s menus and notices only.\n\nCharacter voices and the language you talk in are separate."] = "Змінює лише меню й сповіщення цього моду.\n\nГолоси персонажів і мова, якою ти розмовляєш, налаштовуються окремо.",
    ["Characters sometimes ask about something you said, pick up something from earlier or share a thought that invites an answer.\n\nNow and then, never on every reply, and never while you are leaving, giving an order or fighting."] = "Персонажі іноді питають про те, що ти сказав, згадують щось із попереднього або діляться думкою, на яку хочеться відповісти.\n\nІнколи, але не в кожній відповіді, і ніколи, коли ти йдеш, даєш наказ або б’єшся.",
    ["Chat history stays available across game launches.\n\nForgetting a character also clears their saved Chat messages and drafts. Forgetting all memories clears all saved chats."] = "Історія чату зберігається між запусками гри.\n\nЯкщо забути персонажа, також очищаються його збережені повідомлення чату та чернетки. Якщо забути всю пам’ять, очищаються всі збережені чати.",
    ["Cinematic: the game’s regular dialogue subtitles.\n\nAbove the speaker: over the companion who is talking.\n\nThe Subtitles switch turns both off."] = "Кінематографічні: звичайні субтитри діалогів гри.\n\nНад мовцем: над компаньйоном, який говорить.\n\nПеремикач «Субтитри» вимикає обидва варіанти.",
    ["Companions comment after you finish collecting loot from the world. Storage transfers stay silent.\n\nOrdinary comments are ten minutes apart; newly acquired Legendary gear has its own two-minute cooldown.\n\nPickups made during a fight are folded into one comment at its end."] = "Компаньйони коментують після збирання здобичі у світі. Переміщення в сховищі залишаються без коментарів.\n\nЗвичайні коментарі з’являються раз на десять хвилин; нове спорядження Legendary має власну двохвилинну паузу.\n\nПідбирання під час бою об’єднуються в один коментар наприкінці бою.",
    ["Companions gesture while they speak longer replies and nod while you talk, with the game’s own animations in their usual stance.\n\nThey stop at once when anyone moves or a fight starts."] = "Компаньйони жестикулюють, коли говорять довші репліки, і кивають, поки ти говориш, використовуючи власні анімації гри у звичній позі.\n\nВони одразу припиняють, щойно хтось рухається або починається бій.",
    ["Companions now and then pause, hesitate, laugh or sigh, as their personality would. Each character decides when; it stays rare.\n\nOmniVoice can voice laughs and sighs; the other voices only add pauses.\n\nNot available with Convai’s cloud voice: choosing it turns this off, and turning this on switches the voice to Pocket."] = "Компаньйони час від часу роблять паузи, вагаються, сміються чи зітхають — відповідно до характеру. Кожен персонаж сам вирішує, коли; це відбувається рідко.\n\nOmniVoice може озвучувати сміх і зітхання; інші голоси додають лише паузи.\n\nНедоступно з хмарним голосом Convai: його вибір вимикає це, а ввімкнення перемикає голос на Pocket.",
    ["Copy your free key from Mistral first (signing up there needs phone verification). It is read from the clipboard once, checked with Mistral and saved on this computer.\n\nYou can also save it in player-mistral-key.txt in the conversation service folder. Mistral allows about one message a second and about 5,000 turns a day. It sets its own monthly cap, estimated at about 150,000 turns."] = "Спершу скопіюй безкоштовний ключ із Mistral (реєстрація потребує підтвердження телефону). Його один раз зчитують із буфера обміну, перевіряють у Mistral і зберігають на цьому комп’ютері.\n\nТакож його можна зберегти у файлі player-mistral-key.txt у папці служби розмов. Mistral дозволяє приблизно одне повідомлення на секунду та приблизно 5 000 повідомлень на день. Місячний ліміт встановлює сам Mistral, орієнтовно 150 000 повідомлень.",
    ["Copy your key from Inworld first. It is read from the clipboard once, checked with Inworld and saved on this computer.\n\nYou can also save it in player-inworld-key.txt in the conversation service folder. It is used only for the Inworld voice."] = "Спершу скопіюй ключ з Inworld. Його один раз зчитують із буфера обміну, перевіряють в Inworld і зберігають на цьому комп’ютері.\n\nТакож його можна зберегти у файлі player-inworld-key.txt у папці служби розмов. Він використовується лише для голосу Inworld.",
    ["Custom models are ones you added; they join the default choice by size."] = "Власні моделі — це ті, що ти додав; вони беруть участь у типовому виборі за розміром.",
    ["Each character marks its own feelings as it speaks, so the face changes at that word instead of being guessed from the text. Subtle, set by personality, only where a feeling really shifts.\n\nNot available with Convai’s cloud voice: choosing it turns this off, and turning this on switches the voice to Pocket."] = "Кожен персонаж позначає свої почуття під час мовлення, тож обличчя змінюється саме на цьому слові, а не вгадується з тексту. Тонко, залежно від характеру й лише там, де почуття справді змінюється.\n\nНедоступно з хмарним голосом Convai: його вибір вимикає це, а ввімкнення перемикає голос на Pocket.",
    ["Eyes only: the head stays still and just the eyes move.\n\nSubtle to Strong: the head turns toward you more and more."] = "Лише очі: голова нерухома, рухаються тільки очі.\n\nВід слабкого до сильного: голова дедалі більше повертається до тебе.",
    ["For testing and bug reports; leave it off for normal play.\n\nShows routine popups (joining steps, dismissals, driving instructions, results of companion actions), writes a movement trace in the mod’s runtime folder, logs gesture decisions and adds itself to support reports.\n\nPreparation progress, joined notices, failures and replies to Stop trip stay visible when it is off."] = "Для тестів і звітів про помилки; у звичайній грі вимкни.\n\nПоказує службові спливаючі вікна (кроки приєднання, закриття, вказівки щодо водіння, результати дій компаньйонів), записує трасу руху в робочу папку моду, веде журнал рішень щодо жестів і додається до звітів підтримки.\n\nХід підготовки, сповіщення про приєднання, помилки та відповіді на «Зупинити поїздку» лишаються видимими, коли це вимкнено.",
    ["Forget all memories applies to these characters.\n\nBrowsing the catalogue or inviting a companion does not add anyone to this count."] = "«Забути всю пам’ять» стосується цих персонажів.\n\nПерегляд каталогу чи запрошення компаньйона нікого не додає до цього лічильника.",
    ["Gang members, NCPD officers, guards, ripperdocs, shopkeepers, bartenders and passers-by answer as their kind of person.\n\nThey do not know your story and forget you after a save load, except shopkeepers you come back to.\n\nNamed characters are not affected."] = "Члени банд, офіцери NCPD, охоронці, рипердоки, продавці, бармени й перехожі відповідають як представники свого кола.\n\nВони не знають твоєї історії й забувають тебе після завантаження збереження, окрім продавців, до яких ти повертаєшся.\n\nІменовані персонажі не змінюються.",
    ["Gets a conversation ready when you look at, approach or have just talked to a character, so they answer without a wait. Paused in combat and scenes.\n\nLimits: two characters ready at once, a new one every 3 s, released after 40 s unused. A crowd never adds up."] = "Готує розмову, коли ти дивишся на персонажа, підходиш до нього або щойно з ним говорив, тож він відповідає без очікування. Призупиняється в бою та сценах.\n\nОбмеження: два персонажі одночасно, новий — кожні 3 s, звільняється через 40 s без використання. Натовп не додає до цього числа.",
    ["If a character stops answering, voices stop or an error appears: choose Generate report and send the file it names to the developer, with a short note about what you were doing.\n\nThe logs listed below show what went wrong."] = "Якщо персонаж перестає відповідати, голоси зникають або з’являється помилка: вибери «Згенерувати звіт» і надішли розробнику файл, який він назве, з коротким описом того, що ти робив.\n\nЖурнали, перелічені нижче, показують, що пішло не так.",
    ["Invited characters are prepared immediately. Their memories start when you actually talk to them.\n\nOne player identity is shared across all saves and stays the same after forgetting.\n\nCurrent game context describes the world you have loaded."] = "Запрошені персонажі готуються одразу. Їхня пам’ять починається, коли ти справді заговориш із ними.\n\nОдна особистість гравця спільна для всіх збережень і лишається незмінною після забуття.\n\nПоточний контекст гри описує завантажений світ.",
    ["Inworld · Cloud voice"] = "Inworld · Хмарний голос",
    ["Inworld · needs key"] = "Inworld · потрібен ключ",
    ["Judy, Panam, River, Kerry and Meredith can speak as a partner or in their ordinary manner.\n\nAuto follows the relationship in your save."] = "Judy, Panam, River, Kerry і Meredith можуть говорити як партнери або у своїй звичній манері.\n\nАвто орієнтується на стосунки у твоєму збереженні.",
    ["Needs the Local AI pack."] = "Потрібен пакет Локального ШІ.",
    ["Never allowed: sex with minors or without consent, sex about real people, hate, real-world weapon or drug instructions. A safety check enforces the minors rule."] = "Заборонено: секс з неповнолітніми, без згоди, про реальних людей, ненависть, інструкції зі зброї чи наркотиків. Заборону для неповнолітніх перевіряють.",
    ["Off: replies are text only and no voice is generated.\n\nWith Subtitles off as well, automatic reactions stay silent."] = "Вимкнено: відповіді лише текстові, голос не створюється.\n\nЯкщо вимкнено й субтитри, автоматичні реакції залишаються без звуку.",
    ["Pocket: the lightest, runs on your CPU, starts speaking in about 0.2 s.\n\nOmniVoice: richer, especially on harder voices. Needs a capable GPU and the OmniVoice pack (greyed out until it is installed); the higher tiers start in 1 to 2.5 s.\n\nVoxtral: each companion’s own voice from the cloud, with your own Mistral key, English only. It loads no local voice model.\n\nConvai: its own cloud voice. A voice that cannot run is replaced by a simpler one, with one notice."] = "Pocket: найлегший, працює на процесорі, починає говорити приблизно за 0.2 s.\n\nOmniVoice: багатший, особливо на складних голосах. Потрібна потужна відеокарта й пакет OmniVoice (неактивний, доки його не встановлено); старші рівні стартують за 1–2.5 s.\n\nVoxtral: власний голос кожного компаньйона з хмари, з твоїм ключем Mistral, лише англійською. Він не завантажує локальну модель голосу.\n\nConvai: власний хмарний голос. Голос, який не може працювати, замінюється простішим, з одним сповіщенням.",
    ["Right after the game’s own dialogue with a character, they know its last few lines, including your chosen replies and your phone calls with them.\n\nOnly the last few minutes count, and none of it is saved to memory."] = "Одразу після власного діалогу гри з персонажем він знає його останні репліки, зокрема твої обрані відповіді та телефонні розмови з ним.\n\nВраховуються лише останні кілька хвилин, і нічого з цього не зберігається в пам’ять.",
    ["See what each character remembers and make one or all of them forget.\n\nMemories are kept across saves."] = "Переглянь, що пам’ятає кожен персонаж, і зітри пам’ять одного або всіх.\n\nСпогади зберігаються між збереженнями.",
    ["Shows companion replies as text.\n\nWith Voice playback off as well, automatic reactions stay silent."] = "Показує відповіді компаньйонів текстом.\n\nЯкщо відтворення голосу теж вимкнено, автоматичні реакції лишаються без звуку.",
    ["Shows the character live in a holocall instead of their portrait.\n\nExperimental: the picture can stay empty. If she cannot be shown, the call goes on with the portrait."] = "Показує персонажа в голодзвінку наживо замість портрета.\n\nЕкспериментально: зображення може лишитися порожнім. Якщо її не вдається показати, дзвінок триває з портретом.",
    ["Strong language, graphic violence, drugs and, between consenting adults, flirting and sex. Adults only (18+), Local AI only."] = "Нецензурна лексика, жорстокість, наркотики та, між дорослими за згодою, фліртування й секс. Лише 18+, лише Локальний ШІ.",
    ["Talk in any language; each character answers in yours.\n\nA separate multilingual copy of each character is used, so what they remember from these talks stays apart from your English ones. Forgetting a character clears both.\n\nPocket and Voxtral speak English only, so this switches the voice to OmniVoice · Balanced, or to Convai · Cloud voice without the OmniVoice pack. Without the pack, Natural speech and Expressive emotions turn off."] = "Розмовляй будь-якою мовою; кожен персонаж відповідає твоєю мовою.\n\nДля кожного персонажа використовується окрема багатомовна копія, тож його спогади з цих розмов відокремлені від англійських. Якщо забути персонажа, очищаються обидві.\n\nPocket і Voxtral говорять лише англійською, тож ця опція перемикає голос на OmniVoice · Збалансований або на Convai · Хмарний голос без пакета OmniVoice. Без пакета «Природне мовлення» й «Виразні емоції» вимикаються.",
    ["Turning it on also selects Local AI, the largest uncensored model that fits and a local voice instead of a cloud one. Turning it off restores your choices."] = "Увімкнення обирає Локальний ШІ, найбільшу підхожу модель без цензури й локальний голос замість хмарного. Вимкнення повертає вибір.",
    ["Use it if companions seem to look above or below your eyes."] = "Вмикай, якщо компаньйони ніби дивляться вище або нижче твоїх очей.",
    ["Voxtral · Mistral cloud"] = "Voxtral · Хмара Mistral",
    ["Voxtral · needs Mistral key"] = "Voxtral · треба ключ Mistral",
    ["When you type a line, V says it out loud too, in the male or female V voice that matches yours. Push-to-talk is never replayed.\n\nV speaks first, then the companion answers. A slow V line is skipped, so the reply is never delayed.\n\nUses the voice chosen above, cloned for V."] = "Коли ти вводиш репліку, V теж озвучує її вголос — чоловічим або жіночим голосом V, що відповідає твоєму. Ввід через push-to-talk ніколи не відтворюється повторно.\n\nV говорить першим, потім відповідає компаньйон. Повільна репліка V пропускається, тож відповідь ніколи не затримується.\n\nВикористовується голос, вибраний вище, клонований для V.",
    ["{name} (custom · too large)"] = "{name} (власна · завелика)",
    ["{name} (custom, {size} GB, needs {need} GB)"] = "{name} (власна, {size} GB, потрібно {need} GB)",
    ["{name} (custom, {size} GB, too large for this card)"] = "{name} (власна, {size} GB, завелика для цієї відеокарти)",
    ["Clear memories about you for every character you have talked to.\n\nYour player identity stays. A confirmation comes first."] = "Очисти пам’ять про тебе у всіх персонажів, з якими відбувалися розмови.\n\nІдентичність гравця зберігається. Спершу потрібне підтвердження.",
    ["Saves a report file you can send to the developer.\n\nAPI keys, tokens, IDs, microphone audio and conversation text are left out. Without the conversation service, a shorter report is made from the files the game can read."] = "Збережи файл звіту, який можна надіслати розробнику.\n\nAPI-ключі, токени, ідентифікатори, звук мікрофона й текст розмов не включаються. Без служби розмов створюється коротший звіт із файлів, які може прочитати гра.",
    ["The Mature pack’s uncensored models give the full effect; standard models mostly refuse sex. Pack: installed."] = "Моделі без цензури з Mature pack дають повний ефект; звичайні часто відмовляють у сексі. Пакет: встановлено.",
    ["The Mature pack’s uncensored models give the full effect; standard models mostly refuse sex. Pack: not installed (optional, on this mod’s GitHub page)."] = "Моделі без цензури з Mature pack дають повний ефект; звичайні часто відмовляють у сексі. Пакет: не встановлено (необов’язково, сторінка на GitHub).",
    ["Until you choose one, Local AI loads the largest model that fits your free graphics memory.\n\nOne model at a time; a change applies when it next loads. A model that is missing, too large or failing is replaced by the largest that fits, with one notice."] = "Без вибору, Локальний ШІ завантажує найбільшу модель, що вміститься у вільну відеопам’ять.\n\nОдна модель за раз; зміна діє при наступному завантаженні. Відсутню, завелику або збійну модель замінює найбільша підхожа, з одним сповіщенням.",
    ["Body gestures"] = "Жести тілом",
    ["Convai did not accept your API key. Check it in Settings > Conversation provider."] = "Convai не прийняв твій API-ключ. Перевір його в меню Налаштування > Постачальник розмов.",
    ["Local AI could not start, so a cloud provider is used. Check Local AI in Settings > Conversation provider."] = "Локальний ШІ не вдалося запустити, тож використовується хмарний провайдер. Перевір Локальний ШІ в меню Налаштування > Постачальник розмов.",
    ["Local AI could not start. Check Local AI in Settings > Conversation provider."] = "Локальний ШІ не вдалося запустити. Перевір Локальний ШІ в меню Налаштування > Постачальник розмов.",
    ["Mistral did not accept your key. Check it in Settings > Conversation provider."] = "Mistral не прийняв твій ключ. Перевір його в меню Налаштування > Постачальник розмов.",
    ["Mistral has no key yet, so Convai is used. Add your key in Settings > Conversation provider."] = "Для Mistral ще немає ключа, тож використовується Convai. Додай свій ключ у меню Налаштування > Постачальник розмов.",
    ["Requires a Mistral key (add it in Settings > Conversation provider)"] = "Потрібен ключ Mistral (додай його в Налаштування > Постачальник розмов)",
    ["Requires an Inworld key (add it in Settings > Development)"] = "Потрібен ключ Inworld (додай його в Налаштування > Розробка)",
    ["Speaking to companions needs Convai for now. Set Conversation provider to Convai free tier in Settings > Conversation provider, or type your message."] = "Розмова з компаньйонами поки що потребує Convai. Встанови для параметра Постачальник розмов значення Convai (безкоштовний тариф) в меню Налаштування > Постачальник розмов або напиши повідомлення.",
    ["The conversation limit has been reached. Try again later, or add a free Mistral key and set Conversation provider to Mistral in Settings > Conversation provider."] = "Досягнуто ліміт розмов. Спробуй пізніше або додай безкоштовний ключ Mistral і в меню Налаштування > Постачальник розмов встанови Постачальника розмов: Mistral.",
    ["Your Convai API key has reached its plan limit. Try again later or add a different key in Settings > Conversation provider."] = "Твій API-ключ Convai досяг ліміту тарифу. Спробуй пізніше або додай інший ключ у меню Налаштування > Постачальник розмов.",
    ["You’ve reached today’s Convai free tier limit. It resets tomorrow. To keep talking now, choose another provider in Settings > Conversation provider. Mistral (free, with your own free key) allows about 5,000 turns a day. Local AI is unlimited and runs on your PC."] = "Ти вичерпав сьогоднішній ліміт безкоштовного тарифу Convai. Він оновиться завтра. Щоб продовжити розмову зараз, обери іншого постачальника в меню Налаштування > Постачальник розмов. Mistral (безкоштовно, з твоїм власним безкоштовним ключем) дозволяє приблизно 5 000 повідомлень на день. Локальний ШІ без ліміту і працює на твоєму комп’ютері.",
    ["Today’s {limit} Convai turns are used.\nTry Mistral (free key, ~5,000 a day) or Local AI (unlimited)."] = "Convai: вичерпано {limit}.\nMistral (безкоштовно, ~5 000/день) чи Локальний ШІ (безліміт).",
    ["Today’s Convai turns are used.\nTry Mistral (free key, ~5,000 a day) or Local AI (unlimited)."] = "Ліміт Convai вичерпано.\nMistral (безкоштовно, ~5 000/день) чи Локальний ШІ (безліміт).",
    ["You have used today’s {limit} turns, which come back tomorrow. To keep talking now, choose Mistral (with your free key, about 5,000 turns a day) or Local AI (unlimited), then Apply."] = "Ти вже використав свої {limit} повідомлень на сьогодні. Вони відновляться завтра. Щоб продовжити зараз, обери Mistral (з безкоштовним ключем, орієнтовно 5 000 повідомлень на день) або Локальний ШІ (без ліміту), потім Застосувати.",
    ["Convai is answering right now, so these changes have no effect yet. Choose Mistral or Local as the conversation provider in the settings."] = "Convai зараз відповідає, тому ці зміни поки не діють. Вибери в налаштуваннях Mistral або Local як постачальника розмов.",
    ["Edit a character’s bio, speaking style, speaking rules and memories in your browser.\n\nWorks with Mistral and Local, not Convai. Changes apply from the next reply."] = "Редагуй біографію персонажа, манеру мовлення, правила мовлення та спогади у своєму браузері.\n\nПрацює з Mistral і Локально, але не з Convai. Зміни діють із наступної відповіді.",
    ["Who writes your companions’ replies. A change waits until no conversation is running; choose Apply.\n\nConvai free tier needs no setup and gives better replies. Convai API key uses your own key, and Mistral its free plan with your own free key; memory stays on this computer.\n\nWith Mistral or Local, Convai’s cloud voice is replaced by a local voice. Speech is recognized on this computer, so the voice key works."] = "Хто пише відповіді твоїх компаньйонів. Зміна чекатиме, поки жодна розмова не триває; вибери «Застосувати».\n\nБезкоштовний тариф Convai не потребує налаштування і дає кращі відповіді. Ключ API Convai використовує твій ключ, а Mistral працює на безкоштовному тарифі з твоїм безкоштовним ключем; пам’ять лишається на цьому комп’ютері.\n\nЗ Mistral або Локально хмарний голос Convai замінюється локальним голосом. Мовлення розпізнається на цьому комп’ютері, тож голосовий ключ працює.",
    ["Who writes your companions’ replies. A change waits until no conversation is running; choose Apply.\n\nConvai free tier needs no setup and gives better replies. Convai API key uses your own key, and Mistral its free plan with your own free key; memory stays on this computer.\n\nWith Mistral or Local, Convai’s cloud voice is replaced by a local voice. Speech recognition for the voice key is not available yet with them, so type your messages."] = "Хто пише відповіді твоїх компаньйонів. Зміна чекатиме, поки жодна розмова не триває; вибери «Застосувати».\n\nБезкоштовний тариф Convai не потребує налаштування і дає кращі відповіді. Ключ API Convai використовує твій ключ, а Mistral працює на безкоштовному тарифі з твоїм безкоштовним ключем; пам’ять лишається на цьому комп’ютері.\n\nЗ Mistral або Локально хмарний голос Convai замінюється локальним голосом. Розпізнавання мовлення для голосового ключа поки що недоступне, тож вводь повідомлення текстом.",
    ["Your changes work with Mistral and Local. They do not apply to Convai."] = "Твої зміни працюють із Mistral і Local. На Convai вони не діють.",
    ["Choosing a cloud provider turns it off."] = "Вибір хмарного провайдера вимикає це.",
    ["Inworld always speaks with emotion, whatever this says."] = "Inworld завжди говорить з емоціями, незалежно від цього налаштування.",
    ["Inworld can voice laughs and sighs too."] = "Inworld також може озвучувати сміх і зітхання.",
    ["Inworld speaks English only as well."] = "Inworld також говорить лише англійською.",
    ["Inworld: the same with your own Inworld key, and it also speaks with emotion."] = "Inworld: те саме з твоїм ключем Inworld, і він також говорить з емоціями.",
    ["Paste"] = "Вставити",
    ["Works with the Pocket, OmniVoice or Voxtral voices."] = "Працює з голосами Pocket, OmniVoice або Voxtral.",
    ["no Omni pack"] = "без пакета Omni",
}
